/** Material types outside MRO: raw materials, WIP, finished goods, packaging, chemicals, fuels, tools, PPE, lab,
 * IT, office, cleaning, construction, agriculture, medical, food, merchandise and specialised materials. */
import * as L from './library';
import * as X from './library-ext';
import type { TypeSpec, SupplyHint } from './types';

const sup = (usual: SupplyHint[], note: string) => ({ usual, note });
const STD = sup(['OCM', 'GENERAL'], 'Standard item: buy from its maker (OCM) or any distributor using the maker’s product code.');
const GEN = sup(['GENERAL'], 'Commodity: any approved general supplier can supply it against the specification below.');
const PRODUCER = sup(['OCM', 'GENERAL'], 'Buy from the producer (shown as OCM) or its authorised distributor; every batch must match the specification and come with a certificate of analysis.');
const PRINTED = sup(['OCM'], 'Printed or custom-made packaging comes only from the converter approved for this artwork and drawing (OCM). Plain stock items can come from general suppliers.');
const CONSUMABLE = sup(['GENERAL', 'OCM'], 'Generic consumable: general suppliers can offer equivalents; name a reference product so offers can be compared.');
const MATCHED = sup(['OCM', 'GENERAL'], 'Buy by the maker’s product code; say below whether compatible (non-genuine) items are accepted.');
const OWN = sup(['GENERAL'], 'Made in-house or by a contract manufacturer to your own specification — the specification below is what is checked at receipt.');
const FOOD = sup(['GENERAL', 'OCM'], 'Food is bought from approved, food-safety certified suppliers only (ISO 22000 / FSSC / KEBS), against the specification below.');
const MEDICAL = sup(['OCM', 'GENERAL'], 'Medical items only from suppliers licensed by the regulator (PPB) — the maker (OCM) or a licensed distributor. Check registration and expiry on receipt.');

const T = (t: Omit<TypeSpec, 'kind'>): TypeSpec => ({ kind: 'materials', ...t });

